def run(k,apow_list,tb_names):
    e=np.exp(-k*t)
    tbd={'1':np.ones_like(t),'t':t,'t2':t**2,'e':e,'te':t*e}
    cols=[];names=[]
    for an,fa in apow_list:
        for tn in tb_names:
